class Solution {
public:
    vector<int> rotateElements(vector<int>& nums, int k) {
        vector<int> vals;
        for (int x : nums) if (x >= 0) vals.push_back(x);
        int m = vals.size();
        if (m == 0) return nums;
        k %= m;
        vector<int> ans = nums;
        int j = 0;
        for (int i = 0; i < (int)nums.size(); ++i)
            if (nums[i] >= 0) ans[i] = vals[(j++ + k) % m];
        return ans;
    }
};
